package com.minecraftcodex.casino;
import com.minecraftcodex.casino.commands.CasinoCommand; import com.minecraftcodex.casino.database.Database; import com.minecraftcodex.casino.economy.EconomyService; import com.minecraftcodex.casino.gui.CasinoGui; import com.minecraftcodex.casino.npc.NpcListener; import org.bukkit.command.PluginCommand; import org.bukkit.configuration.file.YamlConfiguration; import org.bukkit.plugin.java.JavaPlugin; import java.io.File; import java.sql.SQLException;
public final class Main extends JavaPlugin { private Database database; private EconomyService economy; private CasinoGui gui; private YamlConfiguration messages;
 public void onEnable(){saveDefaultConfig();saveResource("messages.yml",false);messages=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"messages.yml"));try{database=new Database(getDataFolder());}catch(SQLException e){getLogger().severe("Unable to open casino database: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);return;}economy=new EconomyService(database,getConfig().getDouble("economy.starting-balance"),getServer().getServicesManager());gui=new CasinoGui(this);PluginCommand c=getCommand("casino");c.setExecutor(new CasinoCommand(this));c.setTabCompleter(new CasinoCommand(this));getServer().getPluginManager().registerEvents(gui,this);getServer().getPluginManager().registerEvents(new NpcListener(this),this);}
 public void onDisable(){if(database!=null)try{database.close();}catch(SQLException ignored){}} public Database database(){return database;} public EconomyService economy(){return economy;} public CasinoGui gui(){return gui;} public String message(String key){return messages.getString(key,"&cMissing message: "+key);} }
